#include <math.h>
#include <stddef.h>
#include <stdint.h>
#include <string.h>
static void put_double(uint8_t*out,size_t off,double x){uint64_t b;memcpy(&b,&x,8);for(size_t k=0;k<8;k++)out[off+k]=(uint8_t)(b>>(8*k));}
int64_t n_body_simulation(const int64_t*v,size_t n,uint8_t*out,size_t cap){if(!v||n<6)return -1;int64_t nb=v[0],steps=v[1],dtm=v[2],gm=v[3],tf=v[4],sm=v[5];if(nb<2||nb>4||steps<0||steps>4||dtm<1||dtm>1000||gm<0||gm>1000||tf<1||tf>10||sm<1||sm>3000||n!=6+5*(size_t)nb)return -1;size_t count=(size_t)nb;double x[4],y[4],vx[4],vy[4],mass[4];for(size_t i=0;i<count;i++){int64_t a=v[6+5*i],b=v[7+5*i],c=v[8+5*i],d=v[9+5*i],m=v[10+5*i];if(a < -1000||a>1000||b < -1000||b>1000||c < -100||c>100||d < -100||d>100||m<1||m>1000)return -1;x[i]=a;y[i]=b;vx[i]=c;vy[i]=d;mass[i]=m;}double dt=((double)dtm/1000.0)*(double)tf,g=(double)gm/1000.0,soft=(double)sm/1000.0;for(int64_t step=0;step<steps;step++){for(size_t i=0;i<count;i++){double fx=0,fy=0;for(size_t j=0;j<count;j++)if(i!=j){double dx=x[j]-x[i],dy=y[j]-y[i];double dist=sqrt(dx*dx+dy*dy+soft);double cube=dist*dist*dist;fx+=g*mass[j]*dx/cube;fy+=g*mass[j]*dy/cube;}vx[i]+=fx*dt;vy[i]+=fy*dt;}for(size_t i=0;i<count;i++){x[i]+=vx[i]*dt;y[i]+=vy[i]*dt;}}size_t bytes=count*32;if(!out||cap<bytes)return -2;for(size_t i=0;i<count;i++){put_double(out,(i*4)*8,x[i]);put_double(out,(i*4+1)*8,y[i]);put_double(out,(i*4+2)*8,vx[i]);put_double(out,(i*4+3)*8,vy[i]);}return (int64_t)bytes;}
